/* https://faculdadephorte.edu.br/wp-content/plugins/phorte-cursos-checkout/assets/checkout-shell.css?ver=1.2.2 */
@font-face{font-family:PhortePoppins;src:url(fonts/poppins-400-5feeb1.ttf) format('truetype');font-weight:400;font-display:swap}
@font-face{font-family:PhortePoppins;src:url(fonts/poppins-500-aabd61.ttf) format('truetype');font-weight:500;font-display:swap}
@font-face{font-family:PhortePoppins;src:url(fonts/poppins-600-077aef.ttf) format('truetype');font-weight:600;font-display:swap}
@font-face{font-family:PhortePoppins;src:url(fonts/poppins-700-fdb6e7.ttf) format('truetype');font-weight:700;font-display:swap}
.phorte-checkout-shell,.phorte-minicart{--phorte-red:#d42b2b;--phorte-hover:#a81e1e;--phorte-text:#1a1a1a;--phorte-muted:#595959;--phorte-border:#e5e5e5;--phorte-surface:#f4f6f9;color:var(--phorte-text);font:400 14px/1.6 PhortePoppins,Arial,sans-serif;font-synthesis:none;text-align:left}
.phorte-checkout-shell{max-width:1200px;margin:0 auto;padding:0 32px 48px;width:100%}
.phorte-checkout-shell *,.phorte-minicart *{box-sizing:border-box}
.phorte-checkout-shell [hidden],.phorte-minicart [hidden]{display:none!important}
.phorte-checkout-shell :is(button,input,select,textarea),.phorte-minicart :is(button,input,select,textarea){font:inherit;letter-spacing:normal;text-transform:none}
.phorte-checkout-shell :is(a,button,input,select,textarea):focus-visible,.phorte-minicart :is(a,button,input,select):focus-visible{outline:3px solid #7d1b1b;outline-offset:3px}
.phorte-checkout-shell button,.phorte-minicart button{cursor:pointer}.phorte-checkout-shell button:disabled,.phorte-minicart button:disabled{opacity:.55;cursor:wait}
.phorte-checkout-shell :is(h1,h2,h3,p),.phorte-minicart :is(h2,p){font-family:inherit;color:inherit;letter-spacing:normal;text-transform:none}
.phorte-checkout-shell h1{font-size:29px;font-weight:600;line-height:1.3;letter-spacing:-.8px;margin:8px 0 10px}.phorte-checkout-shell h2{font-size:17px;font-weight:600;line-height:1.4;margin:0 0 16px}.phorte-checkout-shell h3{font-size:14px;font-weight:600;line-height:1.5}
.phorte-checkout-shell a,.phorte-minicart a{color:var(--phorte-hover);text-underline-offset:3px}
.phorte-header{height:88px;border-bottom:1px solid var(--phorte-border);display:flex;align-items:center;justify-content:space-between;gap:20px}.phorte-brand{display:flex;align-items:center;gap:20px;text-decoration:none}.phorte-brand img{width:122px;height:57px;object-fit:contain}.phorte-brand span{padding-left:20px;border-left:1px solid var(--phorte-border);font-size:13px;color:var(--phorte-muted)}.phorte-header-actions{display:flex;align-items:center;gap:24px}.phorte-secure{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--phorte-muted)}.phorte-secure svg{width:15px}
