.phorte-order-details,.phorte-order-addresses{max-width:680px!important;margin:24px auto!important;padding:28px;border:1px solid var(--phorte-border);border-radius:10px}.phorte-order-totals{margin:0;padding:16px 0 0}.phorte-order-totals>div{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--phorte-border);font-size:12px}.phorte-order-totals dt{color:var(--phorte-muted)}.phorte-order-totals dd{margin:0;font-weight:600;text-align:right}.phorte-order-actions{margin-top:24px}.phorte-order-addresses summary{cursor:pointer;font-size:12px;font-weight:600;min-height:44px;display:flex;align-items:center}.phorte-order-addresses summary:after{content:'⌄';margin-left:auto}.phorte-order-addresses .woocommerce-customer-details{font-size:12px}.phorte-order-addresses .woocommerce-column__title{font-size:14px}
