.phorte-checkout-shell .phorte-ddi-toggle{display:inline-flex;align-items:center;gap:8px;flex:none;min-height:46px;padding:0 10px 0 12px;border:0;border-right:1px solid var(--phorte-border);border-radius:6px 0 0 6px;background:#fff;color:var(--phorte-text);font-size:13px;font-weight:500}
