.phorte-checkout-shell .phorte-ddi-panel{position:absolute;z-index:30;top:calc(100% + 6px);left:0;width:min(320px,calc(100vw - 32px));padding:10px;border:1px solid #8c8c8c;border-radius:8px;background:#fff;box-shadow:0 12px 28px rgba(0,0,0,.16)}
.phorte-checkout-shell .phorte-ddi-search{width:100%;min-height:40px;margin:0 0 8px;padding:8px 10px;border:1px solid #7d1b1b;border-radius:6px;font-size:13px}
