.phorte-minicart a.phorte-mini-remove:hover,.phorte-minicart a.phorte-mini-remove:focus{background:var(--phorte-surface)}
.phorte-minicart a.phorte-mini-remove svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2}
.phorte-minicart .phorte-mini-empty{margin:12px 0 4px;padding:18px 0;font-size:13px;color:var(--phorte-muted);text-align:center}

/* 1.1.0 — P1 da revisão de UX (U1–U9). Seletores com .phorte-checkout-shell + .woocommerce para vencer Hello Elementor e WooCommerce. */
.phorte-checkout-shell,.phorte-minicart{--phorte-radius:6px;--phorte-label:#3d3d3d;--phorte-success:#276f3e;--phorte-success-bg:#eef5f1;--phorte-wait:#945201;--phorte-wait-bg:#fcf4eb}
/* U1 — rótulos legíveis, campos de 14px (16px no celular: sem zoom do iPhone), cantos de 6px, alvos de 48px */
.phorte-checkout-shell .woocommerce form .form-row>label:not(.checkbox):not(.woocommerce-form__label-for-checkbox),.phorte-coupon>label{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--phorte-label)}
.phorte-checkout-shell .woocommerce form .form-row>label .required{color:var(--phorte-red)}
.phorte-checkout-shell .woocommerce form .form-row :is(input.input-text,select,textarea),.phorte-checkout-shell .select2-container .select2-selection--single,.phorte-checkout-shell .phorte-coupon input,.phorte-minicart .phorte-coupon input{font-size:14px;border-radius:var(--phorte-radius);min-height:48px}
.phorte-checkout-shell .woocommerce form .form-row :is(input.input-text,select,textarea):focus{border-color:#6b6b6b;box-shadow:inset 0 0 0 1px #6b6b6b}
.phorte-checkout-shell .phorte-primary,.phorte-minicart .phorte-primary,.phorte-checkout-shell #place_order,.phorte-checkout-shell a.checkout-button{border-radius:var(--phorte-radius);font-size:14px;min-height:52px}
.phorte-checkout-shell .phorte-secondary,.phorte-minicart .phorte-secondary,.phorte-checkout-shell .phorte-coupon .phorte-apply-coupon,.phorte-minicart .phorte-coupon .phorte-apply-coupon{border-radius:var(--phorte-radius)}
@media(max-width:767px){.phorte-checkout-shell .woocommerce form .form-row :is(input.input-text,select,textarea),.phorte-checkout-shell .select2-container .select2-selection--single,.phorte-checkout-shell .select2-selection__rendered,.phorte-checkout-shell .phorte-coupon input,.phorte-checkout-shell .phorte-ddi-search,.phorte-minicart .phorte-coupon input{font-size:16px!important}}
/* Etapas: a concluída fica verde */
.phorte-steps li.is-done .phorte-step-number{background:var(--phorte-success-bg);border-color:transparent;color:var(--phorte-success)}
/* U4 — resumo em cartão, com contagem, total em destaque, garantias e ajuda */
@media(min-width:1024px){.phorte-checkout-shell .phorte-checkout-summary{background:#fff;border:1px solid var(--phorte-border);border-radius:12px}}
