.phorte-checkout-shell .woocommerce table.shop_table.phorte-totals-table tfoot tr.order-total :is(th,td){font-size:17px;font-weight:600;padding-top:18px}
.phorte-checkout-shell .woocommerce table.shop_table.phorte-totals-table tfoot tr.order-total td{font-size:24px;font-weight:700;font-variant-numeric:tabular-nums}
.phorte-checkout-shell .phorte-review .phorte-coupon{border-bottom:0;padding:16px 0 0}
.phorte-summary-perks{list-style:none;margin:16px 0 0;padding:16px 0 0;border-top:1px solid var(--phorte-border);display:grid;gap:8px}
