.phorte-summary-perks svg,.phorte-summary-help svg{width:16px;height:16px;flex:none;color:var(--phorte-success)}
.phorte-checkout-shell a.phorte-summary-help{display:flex;align-items:center;gap:8px;min-height:44px;margin-top:8px;font-size:12px;color:var(--phorte-text);text-decoration:none}
.phorte-checkout-shell a.phorte-summary-help strong{color:var(--phorte-hover);text-decoration:underline;text-underline-offset:3px}
.phorte-help-inline .wa__btn_popup,.phorte-help-inline .wa__popup_chat_box{display:none!important}
.phorte-checkout-shell .phorte-summary-label{display:flex;align-items:center;gap:8px;font-weight:600}
.phorte-summary-count{font-weight:400;color:var(--phorte-muted)}
.phorte-summary-chevron{display:grid;place-items:center;transition:transform .2s}.phorte-summary-chevron svg{width:18px;height:18px}
.phorte-summary-toggle[aria-expanded=true] .phorte-summary-chevron{transform:rotate(180deg)}
@media(max-width:1023px){.phorte-checkout-shell .phorte-summary-toggle{min-height:56px;font-size:13px}.phorte-checkout-shell .phorte-summary-total{font-size:16px;font-weight:700}.phorte-checkout-shell .phorte-summary-heading{display:none}}
/* U5 — Stripe sem carteira neste navegador: sem espaço vazio e sem o separador */
.phorte-checkout-shell #wc-stripe-express-checkout-element{min-height:0}
.phorte-checkout-shell #wc-stripe-express-checkout-button-separator.phorte-express-empty{display:none!important}
