/* U6 — totais próprios do carrinho */
.phorte-cart-column{display:grid;gap:16px;min-width:0;align-content:start}
.phorte-checkout-shell a.phorte-back-link{font-size:13px;justify-self:start}
.phorte-cart-products:not(:has(.quantity)) .phorte-cart-actions{display:none}
@media(min-width:1024px){.phorte-checkout-shell .phorte-cart-summary{background:#fff;border:1px solid var(--phorte-border);border-radius:12px}}
.phorte-checkout-shell .phorte-cart-summary .phorte-summary-heading h2{font-size:18px}
.phorte-checkout-shell .phorte-cart-totals .phorte-totals-list{margin:8px 0 0;padding:0}
.phorte-checkout-shell .phorte-totals-list :is(dt,dd){margin:0;font-weight:400}
.phorte-checkout-shell .phorte-totals-list .phorte-grand-total{border-bottom:0;padding-top:18px}
