.phorte-totals-note{margin:10px 0 0;text-align:center;font-size:11px;color:var(--phorte-muted)}
/* U7 — minicarrinho: contador sobre o ícone, botão quadrado */
.phorte-minicart .phorte-cart-toggle{position:relative;width:44px;height:44px;padding:0;border-radius:8px}
.phorte-minicart .phorte-cart-toggle svg{width:20px;height:20px}
