/* U8 e U9 — resultado do pedido: ícone, curso, instruções do Pix no topo, próximos passos */
.phorte-order-status-icon svg{width:28px;height:28px;stroke-width:2.2}
.phorte-order-failed .phorte-order-status-icon,.phorte-order-cancelled .phorte-order-status-icon,.phorte-order-refunded .phorte-order-status-icon{background:#f9ebec;color:#ba0517}
.phorte-checkout-shell .phorte-order-result .phorte-order-courses{margin:-4px 0 10px;font-size:14px;font-weight:500;color:var(--phorte-text)}
.phorte-payment-instructions{margin:24px 0 0;padding:20px;border:1px solid var(--phorte-border);border-radius:10px;background:var(--phorte-surface);text-align:center}
.phorte-payment-instructions img{max-width:220px;height:auto;margin:0 auto}
.phorte-next-steps{margin:24px 0 0;padding:18px 20px;border-radius:10px;background:var(--phorte-success-bg);text-align:left}
