.phorte-next-steps ol{margin:0;padding-left:1.2em;display:grid;gap:6px;font-size:13px}
.phorte-order-actions{display:grid;gap:10px;margin-top:8px}
.phorte-order-actions:empty{display:none}
.phorte-order-actions .phorte-secondary{margin:0}
/* 1.1.0 — Hello Elementor pinta button:hover/:focus de #c36 com texto branco: os botões Phorte mantêm as próprias cores. */
.phorte-minicart .phorte-cart-toggle:is(:hover,:focus,:active),.phorte-checkout-shell .phorte-cart-toggle:is(:hover,:focus,:active){background:#fff;color:var(--phorte-text);border-color:#8c8c8c}
.phorte-minicart .phorte-close-cart:is(:hover,:focus,:active),.phorte-checkout-shell .phorte-ddi-toggle:is(:hover,:focus,:active){background:var(--phorte-surface);color:var(--phorte-text)}
.phorte-checkout-shell .phorte-summary-toggle:is(:hover,:focus,:active){background:var(--phorte-surface);color:var(--phorte-text);border-color:var(--phorte-border)}
.phorte-checkout-shell .phorte-remove-coupon:is(:hover,:focus,:active),.phorte-minicart .phorte-remove-coupon:is(:hover,:focus,:active){background:transparent;color:var(--phorte-hover)}
/* Carrinho: quantidade do livro legível; com JS a quantidade atualiza sozinha e o botão some (sem JS ele continua) */
.phorte-checkout-shell .phorte-cart-products .quantity input.qty{width:76px;min-height:44px;margin-top:10px;padding:8px;border:1px solid #8c8c8c;border-radius:var(--phorte-radius);font-size:14px;text-align:center;background:#fff;color:var(--phorte-text)}
.phorte-checkout-shell.phorte-enhanced .phorte-cart-actions{display:none}
/* Mesmo estilo de rótulo para "Quem fará o pagamento?" */
.phorte-checkout-shell .phorte-person legend{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--phorte-label)}
.phorte-checkout-shell .phorte-review .phorte-coupon{margin-bottom:8px}
/* Aguardando pagamento: os três passos (como no phorte.com) */
.phorte-what-next{list-style:none;margin:24px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;text-align:left;counter-reset:passo}
.phorte-what-next li{counter-increment:passo;display:grid;gap:4px;align-content:start;padding:14px;border:1px solid var(--phorte-border);border-radius:10px;background:var(--phorte-surface);font-size:12px;color:var(--phorte-muted)}
.phorte-what-next li:before{content:counter(passo);display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#fff;border:1px solid var(--phorte-border);font-size:11px;font-weight:700;color:var(--phorte-text)}
.phorte-what-next li strong{font-size:13px;color:var(--phorte-text)}
.phorte-what-next li.is-current{border-color:#9fd3b0;background:var(--phorte-success-bg)}
.phorte-what-next li.is-current:before{background:var(--phorte-success);border-color:var(--phorte-success);color:#fff}
@media(max-width:767px){.phorte-what-next{grid-template-columns:minmax(0,1fr)}}
.phorte-what-next li.is-done:before{content:"\2713";background:var(--phorte-success-bg);border-color:transparent;color:var(--phorte-success)}
/* 1.1.1 — kit do Elementor: sombra 0 0 10px em todo <button> (medido em produção, 03/11) */
.phorte-minicart :is(.phorte-cart-toggle,.phorte-close-cart),.phorte-checkout-shell :is(.phorte-cart-toggle,.phorte-summary-toggle,.phorte-ddi-toggle,.phorte-close-cart,.phorte-apply-coupon),.phorte-checkout-shell #place_order{box-shadow:none;text-shadow:none}
.phorte-minicart :is(.phorte-cart-toggle,.phorte-close-cart):is(:hover,:focus,:active),.phorte-checkout-shell :is(.phorte-summary-toggle,.phorte-ddi-toggle):is(:hover,:focus,:active){box-shadow:none;outline:0}
/* Minicarrinho: fechar 40×40 sem caixa; foco só no teclado; carrinho aberto com borda da marca */
.phorte-minicart .phorte-cart-panel .phorte-close-cart{width:40px;height:40px;min-width:40px;min-height:40px;padding:0;margin:-8px -8px 0 0;border:0;border-radius:6px;background:transparent;color:var(--phorte-text)}
.phorte-minicart .phorte-cart-panel .phorte-close-cart:hover{background:var(--phorte-surface)}
.phorte-minicart .phorte-cart-toggle[aria-expanded=true]{border-color:var(--phorte-hover)}
.phorte-minicart :is(.phorte-cart-toggle,.phorte-close-cart):focus-visible,.phorte-checkout-shell :is(.phorte-summary-toggle,.phorte-ddi-toggle,.phorte-apply-coupon,#place_order):focus-visible,.phorte-minicart .phorte-primary:focus-visible{outline:2px solid var(--phorte-hover);outline-offset:2px}
/* Formas de pagamento e textos legais legíveis (12px/11px em produção) */
