.phorte-checkout-shell .phorte-step-back:focus-visible{outline:2px solid var(--phorte-hover);outline-offset:2px;border-radius:6px}
.phorte-step-note,.phorte-secure-note{display:flex;align-items:center;justify-content:center;gap:8px;flex-basis:100%;margin:4px 0 0;font-size:12px;color:var(--phorte-muted)}
