.phorte-checkout-shell .woocommerce-form-login-toggle .woocommerce-info{display:flex;flex-direction:column;align-items:flex-start;gap:12px;padding:16px 18px;border:1px solid #f4c4c4;border-radius:10px;background:#fff5f5;color:var(--phorte-muted);font-size:13px}
