.phorte-checkout-shell #payment ul.payment_methods{display:grid;gap:12px;border:0!important;border-radius:0;overflow:visible}
.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method{position:relative;border:1px solid var(--phorte-border)!important;border-radius:10px;background:#fff;overflow:hidden}
