.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method>input[type=radio]{position:absolute;right:18px;left:auto;top:27px;margin:0;transform:none}
.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method>label{display:flex;align-items:center;gap:14px;min-height:70px;padding:14px 52px 14px 16px;font-size:14px}
.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method>label .phorte-payment-icon,.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method>label>img{order:-1;width:40px;height:40px;margin:0;padding:9px;border-radius:8px;background:#fdeeee;object-fit:contain;box-sizing:border-box;flex:0 0 auto}
.phorte-pay-text{display:flex;flex-direction:column;gap:2px;min-width:0}
.phorte-pay-name{font-weight:600;color:var(--phorte-text)}
.phorte-pay-sub{font-size:12px;font-weight:400;color:var(--phorte-muted)}
.phorte-checkout-shell #payment ul.payment_methods li.wc_payment_method div.payment_box{margin:0;border-top:1px solid var(--phorte-border);border-radius:0}
/* Resumo: cupom recolhido, subtotal com contagem, 1 curso com imagem grande */
.phorte-coupon-details>summary{display:flex;align-items:center;gap:10px;min-height:44px;cursor:pointer;list-style:none;font-size:13px;color:var(--phorte-text)}
