.phorte-coupon-details>summary svg{width:18px;height:18px;color:var(--phorte-muted)}
.phorte-coupon-details>summary svg:last-child{margin-left:auto;transition:transform .15s}
.phorte-coupon-details[open]>summary svg:last-child{transform:rotate(180deg)}
.phorte-coupon-details[open] .phorte-coupon-input{margin-top:4px}
.phorte-subtotal-count{font-size:12px;font-weight:400;color:var(--phorte-muted)}
.phorte-review-products>.phorte-product:only-child{grid-template-columns:minmax(0,1fr) auto}
.phorte-review-products>.phorte-product:only-child .phorte-product-image{grid-column:1/-1}
.phorte-review-products>.phorte-product:only-child .phorte-product-image img{width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;border-radius:10px}
